    pub(crate) fn resolve(raw: &RawGroupTable, index: &IdentityIndex) -> Result<GroupTable, GraphError> {
        let mut fixed = BTreeMap::new();
        let mut linked = BTreeMap::new();
        let mut fixed_of = BTreeMap::new();
        let mut linked_of = BTreeMap::new();
        let mut claimed_by: BTreeMap<PackageId, GroupName> = BTreeMap::new();

        // One resolution loop parameterized on `GroupKind`, writing into
        // whichever kind's own output maps -- `claimed_by` is shared across
        // both passes exactly as before, so a package claimed by a fixed
        // group still conflicts if a linked group (or a second fixed group)
        // also claims it.
        for (kind, raw_groups, groups, membership) in [
            (GroupKind::Fixed, &raw.fixed, &mut fixed, &mut fixed_of),
            (GroupKind::Linked, &raw.linked, &mut linked, &mut linked_of),
        ] {
            for rg in raw_groups {
                let mut members = Vec::new();
                for name in &rg.members {
                    // Platform manifests take priority: their own native name
                    // is also registered in `index.native` (pointing at their
                    // owner), so `index.resolve` would otherwise resolve them
                    // to `GroupMember::Package(owner)` and silently drop the
                    // platform-manifest membership version.rs's platform-write
                    // derivation depends on.
                    if let Some((owner, path, role)) = index.platform.get(name) {
                        members.push(GroupMember::PlatformManifest {
                            owner: owner.clone(),
                            role: role.clone(),
                            path: path.clone(),
                            name: name.clone(),
                        });
                        continue;
                    }
                    match index.resolve(name) {
                        Ok(id) => {
                            if let Some(other) = claimed_by.get(&id) {
                                if other != &rg.name {
                                    return Err(GraphError::ConflictingGroupMembership {
                                        package: id.clone(),
                                        groups: vec![other.clone(), rg.name.clone()],
                                    });
                                }
                            } else {
                                claimed_by.insert(id.clone(), rg.name.clone());
                            }
                            members.push(GroupMember::Package(id.clone()));
                            membership.insert(id, rg.name.clone());
                        }
                        // Ambiguous is a real, reportable error (E103), not a
                        // "try the next lookup" miss.
                        Err(err @ GraphError::AmbiguousName { .. }) => return Err(err),
                        Err(_) => {
                            return Err(GraphError::MissingGroupMember {
                                group: rg.name.clone(),
                                member: name.clone(),
                            });
                        }
                    }
                }
                members.sort();
                groups.insert(
                    rg.name.clone(),
                    GroupDef {
                        name: rg.name.clone(),
                        kind,
                        members,
                    },
                );
            }
        }

        Ok(GroupTable {
            fixed,
            linked,
            fixed_of,
            linked_of,
        })
    }

    pub fn fixed_group_of(&self, id: &PackageId) -> Option<&GroupDef> {
        let name = self.fixed_of.get(id)?;
        self.fixed.get(name)
    }

    pub fn linked_group_of(&self, id: &PackageId) -> Option<&GroupDef> {
        let name = self.linked_of.get(id)?;
        self.linked.get(name)
    }

    pub fn fixed_siblings<'a>(&'a self, id: &'a PackageId) -> impl Iterator<Item = &'a PackageId> {
        let mut sibs = Vec::new();
        if let Some(g) = self.fixed_group_of(id) {
            for m in g.members(GroupMemberKind::Package) {
                if let GroupMember::Package(ref pkg_id) = m {
                    if pkg_id != id {
                        sibs.push(pkg_id);
                    }
                }
            }
        }
        sibs.into_iter()
    }

    /// Builds a table from resolved groups, rejecting an empty group, a repeated
    /// group name, and a package claimed twice, with the same errors config loading reports.
    ///
    /// # Errors
    ///
    /// [`ConfigError::DuplicateGroupName`], [`ConfigError::EmptyGroup`],
    /// [`ConfigError::DuplicateMemberInGroup`] or [`ConfigError::ConflictingGroupNames`].
    pub fn try_from_groups(fixed: Vec<GroupDef>, linked: Vec<GroupDef>) -> Result<Self, ConfigError> {
        let members = |groups: &[GroupDef]| -> Vec<(GroupName, Vec<String>)> {
            groups
                .iter()
                .map(|g| {
                    let members = g
                        .members
                        .iter()
                        .map(|member| match member {
                            GroupMember::Package(id) => id.to_string(),
                            GroupMember::PlatformManifest { name, .. } => name.clone(),
                        })
                        .collect();
                    (g.name.clone(), members)
                })
                .collect()
        };
        Self::validate_membership(&members(&fixed), &members(&linked))?;
        Ok(Self::assemble(fixed, linked))
    }

    /// Builds a table without validating it: a package claimed by two groups silently
    /// keeps the last claim.
    #[deprecated(note = "use `try_from_groups`, which rejects conflicting group membership")]
    pub fn from_groups(fixed: Vec<GroupDef>, linked: Vec<GroupDef>) -> Self {
        Self::assemble(fixed, linked)
    }

    fn assemble(fixed: Vec<GroupDef>, linked: Vec<GroupDef>) -> Self {
        let mut f_map = BTreeMap::new();
        let mut l_map = BTreeMap::new();
        let mut f_of = BTreeMap::new();
        let mut l_of = BTreeMap::new();

        for g in fixed {
            for m in g.members(GroupMemberKind::Package) {
                if let GroupMember::Package(ref id) = m {
                    f_of.insert(id.clone(), g.name.clone());
                }
            }
            f_map.insert(g.name.clone(), g);
        }

        for g in linked {
            for m in g.members(GroupMemberKind::Package) {
                if let GroupMember::Package(ref id) = m {
                    l_of.insert(id.clone(), g.name.clone());
                }
            }
            l_map.insert(g.name.clone(), g);
        }

        GroupTable {
            fixed: f_map,
            linked: l_map,
            fixed_of: f_of,
            linked_of: l_of,
        }
    }
}

